R = []
HEADS = 'Головы и панцири креветок'
PREP = 'заготовка'

def shrimp_swap(minus, grams, how):
    return dict(name='С креветками (целые — головы на склад)', minus=minus, yields=[HEADS],
                ing=[['Креветки целые (с головой)', grams * 2, 'г', {'note': f'≈{grams} г мяса; очищенные тоже ок — тогда {grams} г'}]], note=how)

